fun hostMatches(pattern: String, host: String): Boolean {
    val p = pattern.lowercase().trimEnd('.')
    val h = host.lowercase().trimEnd('.')
    if (!p.startsWith("*.")) return p == h          // no wildcard: exact match
    val rest = p.substring(1)                         // "*.pay.test" -> ".pay.test"
    if (!h.endsWith(rest)) return false
    val label = h.dropLast(rest.length)               // what the * stands for
    return label.isNotEmpty() && '.' !in label        // exactly one label
}

